{
  "claims": [
    {
      "quote": "PHOENIX, AZ. (July 3, 2015) – Theranos, Inc. (Theranos) today applauded Arizona’s groundbreaking new Direct Access law, an important step toward a new era of preventive health care in our country.",
      "kind": "specific",
      "why": "This claim can be checked against the date July 3, 2015, and the enactment of Arizona's Direct Access law."
    },
    {
      "quote": "Theranos lab tests are available in forty-two Theranos Wellness Centers in the Phoenix area, and Theranos is now expanding throughout the state.",
      "kind": "specific",
      "why": "This can be verified by checking the number of Theranos Wellness Centers operating in the Phoenix area."
    },
    {
      "quote": "The legislation that enabled this change makes Arizona the first state to institute this comprehensive framework for laboratory testing, expressly recognizing individual’s rights to their own health information.",
      "kind": "specific",
      "why": "This claim can be checked against legislative history to verify if Arizona was indeed the first state."
    },
    {
      "quote": "Theranos, Inc. is a consumer health technology company founded in 2003 by Elizabeth Holmes.",
      "kind": "specific",
      "why": "This can be verified by checking corporate registration records and the founding year 2003 alongside Elizabeth Holmes."
    },
    {
      "quote": "Lab test data drive more than 70% of health decisions.",
      "kind": "specific",
      "why": "This statistic can be checked against medical industry research regarding the percentage of health decisions driven by lab data."
    },
    {
      "quote": "Theranos’ revolutionary lab services make tests more efficient, convenient, and affordable than ever before.",
      "kind": "vague",
      "why": "This claim relies entirely on subjective promotional adjectives like revolutionary, efficient, convenient, and affordable without specific metrics."
    },
    {
      "quote": "Theranos offers a comprehensive menu of lab tests in convenient locations in its Walgreens Wellness Centers in Arizona and California, with plans to expand throughout the country.",
      "kind": "specific",
      "why": "This can be checked by verifying the partnership locations in Walgreens Wellness Centers across Arizona and California."
    },
    {
      "quote": "Theranos also worked with Representative Heather Carter, Senator Nancy Barto, and many leaders in the physician community.",
      "kind": "specific",
      "why": "This can be verified by checking the legislative records and participants associated with Representative Heather Carter and Senator Nancy Barto."
    }
  ]
}

